def compare_one(a, b):
    """
    Compare two values (int, float, or string representing a number) and return the larger one
    in its original type. Return None if they are equal.
    """
    # Helper to convert string numbers (with commas as thousand separators) to float
    def to_number(x):
        try:
            if isinstance(x, str):
                # Replace comma with dot for float conversion
                return float(x.replace(',', '.'))
            return float(x)
        except ValueError:
            # If conversion fails, keep original type (not ideal but per spec)
            return x

    num_a = to_number(a)
    num_b = to_number(b)

    if num_a > num_b:
        # Return original type of a
        if isinstance(a, str):
            return a
        return a
    elif num_b > num_a:
        # Return original type of b
        if isinstance(b, str):
            return b
        return b
    else:
        return None
