import re

def words_in_sentence(sentence: str) -> str:
    """
    Returns a string containing only the words from the input sentence whose lengths are prime numbers,
    preserving the original order and spacing between them (words are separated by a single space).
    """
    # Find all words (using split() to handle multiple spaces, but sentence has only letters and spaces)
    words = sentence.split()

    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    filtered_words = [w for w in words if is_prime(len(w))]

    # Join the filtered words with a single space
    return ' '.join(filtered_words)
